dialog_path = Path('services/agent-service/src/agent_core/lifecycle/dialogue_runtime.py')
dialog_text = dialog_path.read_text(encoding='utf-8')
old = '''    feedback = data.get("independent_verifier_feedback") if isinstance(data.get("independent_verifier_feedback"), dict) else {}\n    authority = str(feedback.get("authority") or "")\n    if authority == "candidate_blind_goal_inventory":\n        field = "goal_inventory"\n    elif authority == "independent_goal_alignment":\n        field = "depends_on"\n    for key in ("uncovered_outcome_spans",):\n'''
